package com.synexia.rewrite;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

/** Exact compiled-fixture ownership; host dependencies remain parent-delegated, never host fixtures. */
final class M3MasteryClassLoader extends ClassLoader {
    private final Map<String, byte[]> classes;
    private final Runnable checkCanceled;

    M3MasteryClassLoader(Map<String, byte[]> classes, ClassLoader parent) {
        this(classes, parent, () -> {});
    }

    M3MasteryClassLoader(Map<String, byte[]> classes, ClassLoader parent, Runnable checkCanceled) {
        super(parent);
        this.checkCanceled = Objects.requireNonNull(checkCanceled, "checkCanceled");
        Map<String, byte[]> frozen = new LinkedHashMap<>();
        Objects.requireNonNull(classes, "classes").forEach((name, bytes) -> {
            this.checkCanceled.run();
            Objects.requireNonNull(name, "class name");
            if (name.isBlank() || name.startsWith("java.")) {
                throw new IllegalArgumentException("invalid fixture class: " + name);
            }
            frozen.put(name, Objects.requireNonNull(bytes, "class bytes").clone());
        });
        this.classes = Map.copyOf(frozen);
    }

    @Override
    protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
        checkCanceled.run();
        synchronized (getClassLoadingLock(name)) {
            Class<?> loaded = findLoadedClass(name);
            if (loaded == null) {
                loaded = classes.containsKey(name) ? findClass(name) : super.loadClass(name, false);
            }
            if (resolve) resolveClass(loaded);
            return loaded;
        }
    }

    @Override
    protected Class<?> findClass(String name) throws ClassNotFoundException {
        byte[] bytes = classes.get(name);
        if (bytes == null) throw new ClassNotFoundException(name);
        return defineClass(name, bytes, 0, bytes.length);
    }

    /** Reject a probe/contract accidentally resolved from the embedding host or the platform. */
    static Class<?> requireOwned(ClassLoader loader, String name, boolean initialize)
            throws ClassNotFoundException {
        Class<?> type = Class.forName(name, false, loader);
        if (type.getClassLoader() != loader) {
            throw new AssertionError("fixture class is not owned by compiled image: " + name);
        }
        return initialize ? Class.forName(name, true, loader) : type;
    }
}
